const localized = (item: Product, locale: Locale) => item.title[locale];
const currency = (amount: number, locale: Locale) => `${new Intl.NumberFormat(locale === 'ru' ? 'ru-RU' : locale === 'de' ? 'de-DE' : locale === 'fr' ? 'fr-FR' : 'en-GB', { maximumFractionDigits: 0 }).format(amount)} ₽`;
function ConceptMark({ label = 'Independent portfolio concept' }: { label?: string }) { return <div className="concept-mark"><span className="concept-dot" />{label}</div>; }
function LanguageSwitch({ value, onChange, options }: { value: string; onChange: (v: string) => void; options: string[] }) { return <label className="language-switch"><span className="sr-only">Language</span><select value={value} onChange={e => onChange(e.target.value)}>{options.map(l => <option key={l} value={l}>{l.toUpperCase()}</option>)}</select><ChevronDown size={14} aria-hidden="true" /></label>; }

function Aurelia() {
  const [locale, setLocale] = useState<Locale>('ru'); const [category, setCategory] = useState('all'); const [query, setQuery] = useState(''); const [sort, setSort] = useState('catalog'); const [cartOpen, setCartOpen] = useState(false); const [modalItem, setModalItem] = useState<Product | null>(null); const [booking, setBooking] = useState(false); const [menuOpen, setMenuOpen] = useState(false); const [notice, setNotice] = useState(''); const t = text[locale];
  const [cart, setCart] = useState<Record<string, number>>({});
  const results = useMemo(() => { let data = treatments.filter(p => (category === 'all' || p.category === category) && (localized(p, locale).toLowerCase().includes(query.toLowerCase()) || p.description[locale].toLowerCase().includes(query.toLowerCase()))); if (sort === 'low') data = [...data].sort((a, b) => a.price - b.price); if (sort === 'high') data = [...data].sort((a, b) => b.price - a.price); return data; }, [category, query, sort, locale]);
  const count = Object.values(cart).reduce((a, b) => a + b, 0); const total = treatments.reduce((sum, p) => sum + p.price * (cart[p.id] ?? 0), 0);
  const setQty = (id: string, n: number) => setCart(c => { const next = { ...c }; if (n <= 0) delete next[id]; else next[id] = n; return next; });
  const add = (id: string) => { setQty(id, (cart[id] ?? 0) + 1); setNotice(t.add); window.setTimeout(() => setNotice(''), 1800); };
  return <main className="aurelia page-shell">
    <ConceptMark label={t.concept} />
    <header className="aurelia-header"><a href="#top" className="brand-lockup" aria-label="Aurelia home"><span className="aurelia-symbol">A</span><span>AURELIA<small>SKIN STUDIO</small></span></a><button className="mobile-menu-button" aria-expanded={menuOpen} onClick={() => setMenuOpen(!menuOpen)}><Menu size={20} /><span className="sr-only">{t.menu}</span></button><nav className={menuOpen ? 'aurelia-nav is-open' : 'aurelia-nav'} aria-label={t.menu}><a href="#catalog" onClick={() => setMenuOpen(false)}>{t.services}</a><a href="#approach" onClick={() => setMenuOpen(false)}>{t.approach}</a><a href="#questions" onClick={() => setMenuOpen(false)}>{t.faq}</a><a href="#contact" onClick={() => setMenuOpen(false)}>{t.contact}</a></nav><div className="header-actions"><LanguageSwitch value={locale} onChange={v => setLocale(v as Locale)} options={['ru', 'en', 'de', 'fr']} /><button className="bag-button" onClick={() => setCartOpen(true)} aria-label={`${t.basket}, ${count}`}><ShoppingBag size={17} /><span>{count}</span></button><button className="header-book" onClick={() => setBooking(true)}>{t.book}<ArrowUpRight size={14} /></button></div></header>
    <section id="top" className="aurelia-hero"><div className="hero-image" style={{ backgroundImage: `url(\"${asset('r09-1-aurelia-consultation-v2.jpg')}\")` }} role="img" aria-label="A fictional practitioner discussing a care plan with an adult client"/><div className="hero-copy"><p className="hero-index">01 — AURELIA SKIN STUDIO</p><h1>{locale === 'ru' ? <>Процедуры,<br/><em>с ясным планом.</em></> : locale === 'en' ? <>Treatments,<br/><em>with a clear plan.</em></> : locale === 'de' ? <>Behandlungen,<br/><em>mit klarem Plan.</em></> : <>Des soins,<br/><em>en toute clarté.</em></>}</h1><p>{t.intro}</p><a href="#catalog" className="text-link">{t.catalog}<ArrowDown size={16} /></a></div><span className="hero-caption">SKIN / CARE / ROUTINE&nbsp;&nbsp;—&nbsp;&nbsp;CONCEPT 01</span></section>
    <section className="aurelia-catalog section-pad" id="catalog"><div className="section-heading"><div><p className="eyebrow">02 — THE MENU</p><h2>{t.catalog}</h2></div><p>{t.intro}</p></div><div className="catalog-tools"><div className="category-tabs" role="group" aria-label={t.category}>{[['all', t.all], ['face', t.face], ['devices', t.devices], ['consult', t.consult]].map(([key, label]) => <button key={key} className={category === key ? 'tab active' : 'tab'} onClick={() => setCategory(key)} aria-pressed={category === key}>{label}</button>)}</div><div className="catalog-filters"><label className="search-field"><Search size={16} /><span className="sr-only">{t.search}</span><input value={query} onChange={e => setQuery(e.target.value)} placeholder={t.search}/></label><label className="sort-field"><span className="sr-only">{t.sort}</span><select value={sort} onChange={e => setSort(e.target.value)}><option value="catalog">{t.popular}</option><option value="low">{t.low}</option><option value="high">{t.high}</option></select><ChevronDown size={14}/></label></div></div><div className="treatment-list">{results.map((p, i) => <article className="treatment-row" key={p.id}><span className="row-number">0{i + 1}</span><button className="treatment-name" onClick={() => setModalItem(p)}><span>{p.title[locale]}</span><small>{p.description[locale]}</small></button><div className="treatment-meta"><span className="treatment-time"><Clock3 size={14}/>{p.time} {t.min}</span><strong className="treatment-price">{p.price === 0 ? (locale === 'ru' ? 'Бесплатно' : 'Complimentary') : currency(p.price, locale)}</strong></div><button className="row-add" onClick={() => add(p.id)} aria-label={`${t.add}: ${p.title[locale]}`}><Plus size={17}/></button></article>)}{results.length === 0 && <div className="empty-results"><p>{t.noResults}</p><button className="text-link" onClick={() => { setQuery(''); setCategory('all'); }}>{t.reset}<ArrowRight size={15}/></button></div>}</div></section>
    <section className="aurelia-note" id="approach"><div className="note-left"><p className="eyebrow">03 — OUR APPROACH</p><Sparkles size={25} strokeWidth={1}/></div><div className="note-copy"><h2>{t.aboutTitle}</h2><p>{t.aboutBody}</p><div className="steps"><div><span>01</span><strong>{t.step1}</strong><p>{t.step1b}</p></div><div><span>02</span><strong>{t.step2}</strong><p>{t.step2b}</p></div><div><span>03</span><strong>{t.step3}</strong><p>{t.step3b}</p></div></div></div><img src={asset('aurelia-hero.webp')} loading="lazy" alt="Warm-toned skincare still life" /></section>
    <section className="aurelia-faq section-pad" id="questions"><div><p className="eyebrow">04 — NOTES</p><h2>{t.faqTitle}</h2></div><div className="faq-list"><details><summary>{t.q1}<ChevronDown/></summary><p>{t.a1}</p></details><details><summary>{t.q2}<ChevronDown/></summary><p>{t.a2}</p></details><details><summary>{t.q3}<ChevronDown/></summary><p>{t.a3}</p></details></div></section>
    <section className="aurelia-booking" id="contact"><div><p className="eyebrow">05 — NEXT STEP</p><h2>{t.bookTitle}</h2><button className="button button-light" onClick={() => setBooking(true)}>{t.book}<ArrowUpRight size={16}/></button></div><div className="booking-aside"><span>STUDIO NOTE / 2026</span><p>{t.footer}</p></div></section>
    <footer className="aurelia-footer"><a href="#top" className="brand-lockup"><span className="aurelia-symbol">A</span><span>AURELIA<small>SKIN STUDIO</small></span></a><span>INDEPENDENT PORTFOLIO CONCEPT</span><a href="../../index.html">Studio portfolio <ArrowUpRight size={14}/></a></footer>
    {notice && <div className="live-toast" role="status">{notice}</div>}
    {cartOpen && <div className="drawer-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setCartOpen(false); }}><aside className="cart-drawer" aria-label={t.basket}><div className="drawer-head"><div><p className="eyebrow">AURELIA / YOUR EDIT</p><h2>{t.basket}</h2></div><button className="icon-button" onClick={() => setCartOpen(false)} aria-label={t.close}><X/></button></div>{count === 0 ? <div className="cart-empty"><ShoppingBag size={25}/><p>{t.empty}</p><button className="text-link" onClick={() => setCartOpen(false)}>{t.services}<ArrowRight size={15}/></button></div> : <><div className="cart-lines">{treatments.filter(p => cart[p.id]).map(p => <div className="cart-line" key={p.id}><div><strong>{p.title[locale]}</strong><small>{p.price ? currency(p.price, locale) : (locale === 'ru' ? 'Без оплаты' : 'No charge')}</small></div><div className="quantity-control"><button onClick={() => setQty(p.id, cart[p.id] - 1)} aria-label="Decrease quantity"><Minus size={14}/></button><span>{cart[p.id]}</span><button onClick={() => setQty(p.id, cart[p.id] + 1)} aria-label="Increase quantity"><Plus size={14}/></button></div><button className="remove-button" onClick={() => setQty(p.id, 0)}>{t.remove}</button></div>)}</div><div className="cart-total"><span>{t.total}</span><strong>{currency(total, locale)}</strong></div><button className="button button-dark full-width" onClick={() => { setCart({}); setNotice(t.checkoutDone + ' — ' + t.checkoutNote); setTimeout(() => setNotice(''), 4000); setCartOpen(false); }}>{t.checkout}<ArrowRight size={16}/></button><p className="cart-disclaimer">{t.checkoutNote}</p></>}</aside></div>}
    {modalItem && <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) setModalItem(null); }}><section className="dialog treatment-dialog" role="dialog" aria-modal="true" aria-labelledby="treatment-title"><button className="icon-button dialog-close" onClick={() => setModalItem(null)} aria-label={t.close}><X/></button><p className="eyebrow">{t.category} / {modalItem.category === 'face' ? t.face : modalItem.category === 'devices' ? t.devices : t.consult}</p><h2 id="treatment-title">{modalItem.title[locale]}</h2><p className="dialog-copy">{modalItem.detail[locale]}</p><div className="detail-meta"><span><Clock3 size={15}/>{modalItem.time} {t.min}</span><strong>{modalItem.price ? currency(modalItem.price, locale) : (locale === 'ru' ? 'Без оплаты' : 'Complimentary')}</strong></div><button className="button button-dark full-width" onClick={() => { add(modalItem.id); setModalItem(null); }}>{t.add}<Plus size={16}/></button></section></div>}
    {booking && <AureliaBooking locale={locale} onClose={() => setBooking(false)}/>}
  </main>;
}

type Service = { id: string; group: string; title: string; desc: string; price: number; duration: string };
const formaServices: Record<'ru' | 'en', Service[]> = {
  ru: [{ id: 'exam', group: 'Профилактика', title: 'Осмотр и план лечения', desc: 'Первичный разговор, осмотр и обсуждение вариантов.', price: 2800, duration: '45 мин' }, { id: 'clean', group: 'Профилактика', title: 'Профессиональная гигиена', desc: 'Демонстрационная позиция прайса, состав уточняется на приёме.', price: 6900, duration: '60 мин' }, { id: 'restore', group: 'Терапия', title: 'Восстановление зуба', desc: 'Формат и объём определяются после осмотра.', price: 8900, duration: 'от 60 мин' }, { id: 'align', group: 'Ортодонтия', title: 'Консультация ортодонта', desc: 'Обсуждение возможных вариантов коррекции прикуса.', price: 3500, duration: '40 мин' }],
  en: [{ id: 'exam', group: 'Preventive', title: 'Exam & care plan', desc: 'An initial conversation, examination, and options review.', price: 2800, duration: '45 min' }, { id: 'clean', group: 'Preventive', title: 'Professional cleaning', desc: 'Sample price list item; scope is discussed at the visit.', price: 6900, duration: '60 min' }, { id: 'restore', group: 'Restorative', title: 'Tooth restoration', desc: 'The format and scope follow an examination.', price: 8900, duration: '60+ min' }, { id: 'align', group: 'Orthodontics', title: 'Orthodontic consultation', desc: 'A conversation about possible alignment options.', price: 3500, duration: '40 min' }]
};
const dentists: Record<'ru' | 'en', { name: string; role: string; letter: string; focus: string }[]> = {
  ru: [{ name: 'Алекс Риверс', role: 'Демонстрационный профиль · терапевтическая стоматология', letter: 'AR', focus: 'бережное объяснение плана' }, { name: 'Мира Коваль', role: 'Демонстрационный профиль · ортодонтия', letter: 'MK', focus: 'понятные варианты коррекции' }, { name: 'Итан Вейл', role: 'Демонстрационный профиль · профилактика', letter: 'EV', focus: 'профилактический уход' }],
  en: [{ name: 'Alex Rivers', role: 'Demo profile · general dentistry', letter: 'AR', focus: 'clear care conversations' }, { name: 'Mira Koval', role: 'Demo profile · orthodontics', letter: 'MK', focus: 'considered alignment options' }, { name: 'Ethan Vale', role: 'Demo profile · prevention', letter: 'EV', focus: 'preventive care planning' }]
};
function Forma() {
  const [locale, setLocale] = useState<'ru' | 'en'>('ru'); const ru = locale === 'ru'; const [filter, setFilter] = useState('all'); const [selectedIndex, setSelectedIndex] = useState(0); const selected = dentists[locale][selectedIndex]; const [date, setDate] = useState(''); const [booking, setBooking] = useState(false); const [faq, setFaq] = useState<number | null>(0); const [menu, setMenu] = useState(false);
  const groups = Array.from(new Set(formaServices[locale].map(x => x.group))); const services = filter === 'all' ? formaServices[locale] : formaServices[locale].filter(s => s.group === filter);
  return <main className="forma page-shell"><ConceptMark label={ru ? 'Демонстрационный концепт · услуги и специалисты вымышлены' : 'Portfolio concept · fictional services and profiles'} /><header className="forma-header"><a className="forma-brand" href="#top"><span className="forma-mark">f.</span><span>FORMA<small>DENTAL STUDIO</small></span></a><button className="mobile-menu-button" aria-expanded={menu} onClick={() => setMenu(!menu)}><Menu/></button><nav className={menu ? 'forma-nav is-open' : 'forma-nav'}>{[[ '#care', ru ? 'Уход' : 'Care'], ['#team', ru ? 'Команда' : 'Team'], ['#prices', ru ? 'Цены' : 'Pricing'], ['#questions', 'FAQ']].map(([href, label]) => <a key={href} href={href} onClick={() => setMenu(false)}>{label}</a>)}</nav><LanguageSwitch value={locale} onChange={v => { setLocale(v as 'ru' | 'en'); setFilter('all'); }} options={['ru','en']}/><button className="forma-cta" onClick={() => setBooking(true)}>{ru ? 'Выбрать дату' : 'Choose a date'}<ArrowUpRight size={14}/></button></header>
    <section className="forma-hero" id="top"><div className="forma-hero-photo"><img src={asset('r09-1-forma-consultation-v2.jpg')} alt="A fictional dentist having a face-to-face conversation with an adult patient"/><span>THE ROOM / STUDY 01</span></div><div className="forma-hero-text"><p className="eyebrow">PRIVATE DENTISTRY / CONCEPT 02</p><h1>{ru ? <>Забота,<br/><em>в которой всё ясно.</em></> : <>Dental care,<br/><em>made considered.</em></>}</h1><p>{ru ? 'Объясняем варианты простым языком и оставляем время на решение.' : 'Clear explanations, thoughtful options, and time to decide.'}</p><a href="#care" className="button button-ink">{ru ? 'Посмотреть услуги' : 'Explore care'}<ArrowRight size={16}/></a><small className="hero-footnote">{ru ? 'Все услуги и цены — демонстрационные.' : 'All services and prices are demo content.'}</small></div></section>
    <section className="forma-manifesto"><span>01 / THE IDEA</span><p>{ru ? 'Хорошее объяснение — часть хорошего приёма. На сайте это начинается с понятных услуг, открытых вопросов и команды без придуманных регалий.' : 'A clear explanation is part of a considered visit. Here that begins with readable services, open questions, and profiles without invented credentials.'}</p><ArrowDown/></section>
    <section className="forma-services" id="care"><div className="forma-heading"><span className="eyebrow">02 / CARE</span><h2>{ru ? 'Сначала — понять.' : 'Begin with clarity.'}</h2><p>{ru ? 'Это пример каталога. Подходящий формат и стоимость в реальной клинике уточняют после осмотра.' : 'A sample service list. A real clinic would confirm scope and cost after an examination.'}</p></div><div className="forma-service-body"><div className="forma-filter"><span>{ru ? 'ПОКАЗАТЬ' : 'FILTER'}</span>{[['all', ru ? 'Все направления' : 'All areas'], ...groups.map(g => [g, g])].map(([key,label]) => <button key={key} className={filter === key ? 'selected' : ''} onClick={() => setFilter(key)}>{label}<ArrowUpRight size={13}/></button>)}</div><div className="forma-service-list" id="prices">{services.map((s, i) => <article className="forma-service" key={s.id}><span className="forma-index">0{i+1}</span><div><h3>{s.title}</h3><p>{s.desc}</p></div><span className="forma-duration">{s.duration}</span><strong>{new Intl.NumberFormat(ru ? 'ru-RU' : 'en-GB').format(s.price)} ₽</strong><button onClick={() => setBooking(true)} aria-label={`${ru ? 'Записаться' : 'Book'}: ${s.title}`}><ArrowUpRight/></button></article>)}</div></div></section>
    <section className="forma-team" id="team"><div className="team-intro"><span className="eyebrow">03 / PEOPLE</span><h2>{ru ? 'Люди, с которыми можно обсудить план.' : 'People to talk a plan through.'}</h2><p>{ru ? 'Вымышленные профили показывают, как может выглядеть раздел команды. Регалии, стаж и реальные данные здесь не заявляются.' : 'Fictional profiles show one possible team layout. No credentials, experience, or real identities are claimed.'}</p></div><div className="team-layout"><div className="dentist-list">{dentists[locale].map((d,index) => <button className={selected.name === d.name ? 'dentist-option chosen' : 'dentist-option'} key={d.name} onClick={() => setSelectedIndex(index)}><span>{d.letter}</span><span>{d.name}<small>{d.role.split('·')[1]}</small></span><ArrowUpRight size={16}/></button>)}</div><article className="dentist-detail"><div className="portrait-placeholder" aria-label={ru ? 'Абстрактный графический портрет, не фото врача' : 'Abstract portrait illustration, not a real clinician photo'}><span>{selected.letter}</span><i>FORMA / PORTRAIT STUDY</i></div><div><span className="eyebrow">PROFILE / DEMO</span><h3>{selected.name}</h3><p>{selected.role}</p><p>{ru ? 'В этом демонстрационном профиле показана область интереса:' : 'This demo profile highlights an area of focus:'} <strong>{selected.focus}</strong>.</p></div></article></div></section>
    <section className="forma-appointment"><div><span className="eyebrow">04 / APPOINTMENT</span><h2>{ru ? 'Выберите дату для демо-записи.' : 'Choose a date for a demo booking.'}</h2><p>{ru ? 'Календарь ничего не отправляет и не резервирует.' : 'The calendar does not submit or reserve anything.'}</p></div><div className="date-picker-panel"><label className="field-label">{ru ? 'Дата визита' : 'Visit date'}<input type="date" value={date} onChange={e => setDate(e.target.value)} onInput={e => setDate(e.currentTarget.value)} min={new Date().toISOString().slice(0, 10)}/></label><button className="button button-ink" disabled={!date} onClick={() => setBooking(true)}>{ru ? 'Продолжить' : 'Continue'}<ArrowRight size={16}/></button><small>{date ? `${ru ? 'Выбрано' : 'Selected'}: ${date}` : ru ? 'Сначала выберите дату' : 'Select a date first'}</small></div></section>
    <section className="forma-faq" id="questions"><div><span className="eyebrow">05 / GOOD TO KNOW</span><h2>{ru ? 'Частые вопросы' : 'Questions, answered'}</h2></div><div>{(ru ? [['Это настоящая клиника?','Нет. Это портфолио-концепт: компания, специалисты, услуги и адрес не существуют.'],['Можно ли записаться?','Можно выбрать демонстрационную дату. Данные не передаются и встреча не создаётся.'],['Как подключить CRM?','При реальном проекте форму можно связать с согласованной CRM и системой записи после настройки обработки персональных данных.']] : [['Is this a real clinic?','No. This is a portfolio concept; the business, team, services, and address are fictional.'],['Can I make an appointment?','You can choose a demo date. Nothing is transmitted and no appointment is created.'],['Can this connect to a CRM?','A real project can connect to an agreed CRM and booking system after personal-data handling is configured.']]).map(([q,a],i) => <div className={faq === i ? 'forma-faq-item open' : 'forma-faq-item'} key={q}><button onClick={() => setFaq(faq === i ? null : i)} aria-expanded={faq === i}>{q}{faq === i ? <Minus/> : <Plus/>}</button>{faq === i && <p>{a}</p>}</div>)}</div></section>
    <footer className="forma-footer"><div className="forma-brand"><span className="forma-mark">f.</span><span>FORMA<small>DENTAL STUDIO</small></span></div><p>{ru ? 'Демонстрационная концепция для портфолио. Не является сайтом клиники.' : 'Portfolio concept. Not a clinic website.'}</p><a href="../../index.html">AI Digital Studio <ArrowUpRight size={14}/></a></footer>
    {booking && <FormaBooking locale={locale} onClose={() => setBooking(false)}/>}
  </main>;
}

type LabTest = { id: string; cat: string; ru: string; en: string; descRu: string; descEn: string; price: number; sample: string };
const labTests: LabTest[] = [
  { id: 'cbc', cat: 'Общий профиль', ru: 'Общий анализ крови', en: 'Complete blood count', descRu: 'Пример позиции каталога с кратким описанием состава.', descEn: 'A sample catalogue entry with a short scope description.', price: 850, sample: 'Blood' },
  { id: 'lipids', cat: 'Биохимия', ru: 'Липидный профиль', en: 'Lipid profile', descRu: 'Демонстрационный набор показателей для каталога.', descEn: 'A demo panel example for the catalogue.', price: 1450, sample: 'Blood' },
  { id: 'thyroid', cat: 'Гормоны', ru: 'Тиреотропный гормон', en: 'Thyroid-stimulating hormone', descRu: 'Одна из возможных строк каталога лаборатории.', descEn: 'One possible entry in a laboratory catalogue.', price: 980, sample: 'Blood' },
  { id: 'vitd', cat: 'Витамины', ru: 'Витамин D', en: 'Vitamin D', descRu: 'Название и стоимость приведены только для демо.', descEn: 'Name and price are shown for demo purposes only.', price: 1650, sample: 'Blood' },
  { id: 'glucose', cat: 'Биохимия', ru: 'Глюкоза', en: 'Glucose', descRu: 'Подготовка зависит от конкретного исследования и лаборатории.', descEn: 'Preparation depends on the specific test and laboratory.', price: 420, sample: 'Blood' },
  { id: 'urine', cat: 'Общий профиль', ru: 'Общий анализ мочи', en: 'Urinalysis', descRu: 'Демонстрационная карточка. Условия сбора уточняются у лаборатории.', descEn: 'Demo card. Collection instructions should come from the laboratory.', price: 690, sample: 'Urine' }
];
function Clarity() {
  const [locale, setLocale] = useState<'ru'|'en'>('ru'); const ru = locale === 'ru'; const [query, setQuery] = useState(''); const [category, setCategory] = useState('all'); const [picked, setPicked] = useState<string[]>([]); const [detail, setDetail] = useState<LabTest|null>(null); const [booking, setBooking] = useState(false); const [menu, setMenu] = useState(false);
  const categories = Array.from(new Set(labTests.map(x => x.cat))); const filtered = labTests.filter(x => (category === 'all' || x.cat === category) && (`${x.ru} ${x.en} ${x.cat}`.toLowerCase().includes(query.toLowerCase())));
  return <main className="clarity page-shell"><div className="clarity-topline"><ConceptMark label={ru ? 'Демо-концепт · медицинские услуги не оказываются' : 'Demo concept · no medical services provided'} /><LanguageSwitch value={locale} onChange={v => setLocale(v as 'ru'|'en')} options={['ru','en']}/></div><header className="clarity-header"><a className="clarity-brand" href="#top"><span className="clarity-symbol"><i/><i/><i/></span><span>clarity<small>DIAGNOSTICS / INDEX</small></span></a><button className="mobile-menu-button" onClick={() => setMenu(!menu)} aria-expanded={menu}><Menu/></button><nav className={menu?'clarity-nav is-open':'clarity-nav'}><a href="#catalog" onClick={() => setMenu(false)}>{ru?'Исследования':'Tests'}</a><a href="#visit" onClick={() => setMenu(false)}>{ru?'Как пройти':'Your visit'}</a><a href="#clarity-faq" onClick={() => setMenu(false)}>FAQ</a></nav><button className="clarity-header-button" onClick={() => setBooking(true)}>{ru?'Подготовить визит':'Plan a visit'}<ArrowUpRight size={15}/></button></header>
    <section className="clarity-hero" id="top"><div className="clarity-hero-copy"><p className="eyebrow">AN INDEX FOR EVERYDAY TESTS / 03</p><h1>{ru ? <>Нужное<br/>исследование.<br/><em>Без лишнего поиска.</em></> : <>Find the test.<br/><em>Skip the guesswork.</em></>}</h1><p>{ru ? 'Найдите нужный пункт каталога и заранее посмотрите, что будет на следующем шаге.' : 'Search a sample catalogue and see what the next step could look like.'}</p><a href="#catalog" className="clarity-search-cta"><Search/>{ru?'Искать исследование':'Search the catalogue'}<ArrowDown/></a><small>{ru?'Каталог носит ознакомительный характер':'Sample catalogue for information architecture only'}</small></div><div className="clarity-hero-image"><img src={asset('r09-1-clarity-lab-v2.jpg')} alt="A fictional Central European laboratory scientist preparing an unlabeled sample"/><span>FIG. 01 / SPECIMEN SERIES</span></div></section>
    <section className="clarity-catalog" id="catalog"><div className="clarity-catalog-heading"><div><p className="eyebrow">01 — RESEARCH DIRECTORY</p><h2>{ru?'Каталог исследований':'Test directory'}</h2><p>{ru?'Ищите по названию или выберите раздел.' : 'Search by name or browse by category.'}</p></div><div className="clarity-searchbox"><Search/><input aria-label={ru?'Поиск исследования':'Search tests'} value={query} onChange={e => setQuery(e.target.value)} placeholder={ru?'Например, витамин D':'Try “vitamin D”'}/>{query && <button onClick={() => setQuery('')} aria-label={ru?'Очистить поиск':'Clear search'}><X/></button>}</div></div><div className="clarity-categories"><button className={category==='all'?'active':''} onClick={() => setCategory('all')}>{ru?'Все разделы':'All categories'} <span>{labTests.length}</span></button>{categories.map(c => <button className={category===c?'active':''} key={c} onClick={() => setCategory(c)}>{ru?c:c === 'Общий профиль'?'General':c === 'Биохимия'?'Biochemistry':c === 'Гормоны'?'Hormones':'Vitamins'}</button>)}</div><div className="test-table"><div className="test-table-head"><span>{ru?'ИССЛЕДОВАНИЕ':'TEST'}</span><span>{ru?'МАТЕРИАЛ':'SAMPLE'}</span><span>{ru?'ПРИМЕР ЦЕНЫ':'SAMPLE PRICE'}</span><span></span></div>{filtered.map(test => <article key={test.id} className="test-row"><div><span className="test-tag">{ru?test.cat: test.cat === 'Общий профиль'?'General':test.cat === 'Биохимия'?'Biochemistry':test.cat === 'Гормоны'?'Hormones':'Vitamins'}</span><button onClick={() => setDetail(test)}>{ru?test.ru:test.en}<small>{ru?test.descRu:test.descEn}</small></button></div><span>{test.sample}</span><strong>{test.price.toLocaleString(ru?'ru-RU':'en-GB')} ₽</strong><button className={picked.includes(test.id)?'test-add selected':'test-add'} onClick={() => setPicked(picked.includes(test.id)?picked.filter(x=>x!==test.id):[...picked,test.id])} aria-label={picked.includes(test.id)?(ru?'Убрать из плана':'Remove from plan'):(ru?'Добавить в план':'Add to plan')}>{picked.includes(test.id)?<Check/>:<Plus/>}</button></article>)}{filtered.length===0&&<p className="clarity-empty">{ru?'Ничего не найдено. Попробуйте другое название.':'No results. Try another search.'}</p>}</div></section>
    <section className="clarity-visit" id="visit"><div><p className="eyebrow">02 — NEXT STEPS</p><h2>{ru?'До визита — несколько понятных шагов.':'A few clear steps before your visit.'}</h2></div><div className="visit-steps"><article><span>01</span><h3>{ru?'Выберите исследование':'Choose a test'}</h3><p>{ru?'Каталог помогает сравнить названия и примерную стоимость.':'Use the sample directory to compare names and indicative prices.'}</p></article><article><span>02</span><h3>{ru?'Уточните подготовку':'Check preparation'}</h3><p>{ru?'Попросите лабораторию объяснить требования именно к выбранному исследованию.':'Ask the laboratory for instructions specific to the test you selected.'}</p></article><article><span>03</span><h3>{ru?'Спланируйте визит':'Plan your visit'}</h3><p>{ru?'Демо-план хранится только в памяти этой страницы.':'Your demo plan stays in this page session only.'}</p></article></div><div className="visit-selection"><div><strong>{ru?'Выбрано исследований':'Selected tests'}: {picked.length}</strong><small>{ru?'План не сохраняется и не отправляется.':'The plan is not saved or sent.'}</small></div><button className="button button-teal" disabled={!picked.length} onClick={() => setBooking(true)}>{ru?'Подготовить визит':'Plan a visit'}<ArrowRight/></button></div></section>
    <section className="clarity-faq" id="clarity-faq"><div><p className="eyebrow">03 — CLARITY NOTES</p><h2>{ru?'Перед тем как продолжить':'Before you continue'}</h2></div><div><details><summary>{ru?'Это действующая лаборатория?':'Is this a real laboratory?'}<ChevronDown/></summary><p>{ru?'Нет, Clarity — концепция для портфолио. Здесь нет точек забора, врачей и медицинских услуг.':'No. Clarity is a portfolio concept with no collection sites, clinicians, or services.'}</p></details><details><summary>{ru?'Можно ориентироваться на цену?':'Can I rely on these prices?'}<ChevronDown/></summary><p>{ru?'Нет. Все цены — демонстрационные значения. У реальной лаборатории стоимость и состав подтверждают официально.':'No. All prices are examples. A real laboratory confirms the test and current price through its official channels.'}</p></details><details><summary>{ru?'Показываются ли результаты?':'Can I see results here?'}<ChevronDown/></summary><p>{ru?'Нет. В концепте нет личного кабинета, результатов анализов или сбора пользовательских данных.':'No. This concept has no patient portal, results, or collection of personal data.'}</p></details></div></section>
    <footer className="clarity-footer"><a className="clarity-brand" href="#top"><span className="clarity-symbol"><i/><i/><i/></span><span>clarity<small>DIAGNOSTICS / INDEX</small></span></a><span>{ru?'Демо-каталог · информация не заменяет консультацию':'Demo catalogue · information is not medical advice'}</span><a href="../../index.html">AI Digital Studio <ArrowUpRight/></a></footer>
    {detail&&<div className="modal-backdrop" onMouseDown={e=>{if(e.currentTarget===e.target)setDetail(null)}}><section className="dialog" role="dialog" aria-modal="true" aria-labelledby="test-title"><button className="icon-button dialog-close" onClick={()=>setDetail(null)} aria-label={ru?'Закрыть':'Close'}><X/></button><span className="eyebrow">{ru?detail.cat:'TEST DIRECTORY'}</span><h2 id="test-title">{ru?detail.ru:detail.en}</h2><p className="dialog-copy">{ru?detail.descRu:detail.descEn} {ru?'Уточните назначение и подготовку у лаборатории.':'Confirm purpose and preparation with the laboratory.'}</p><div className="detail-meta"><span>{ru?'Материал':'Sample'}: {detail.sample}</span><strong>{detail.price.toLocaleString(ru?'ru-RU':'en-GB')} ₽</strong></div><button className="button button-teal full-width" onClick={()=>{setPicked([...new Set([...picked,detail.id])]);setDetail(null)}}>{ru?'Добавить в план':'Add to plan'}<Plus/></button></section></div>}
    {booking&&<ClarityBooking locale={locale} pickedCount={picked.length} onClose={()=>setBooking(false)}/>}
  </main>;
}

